// FARMACOLOGIA BÁSICA
// ═══════════════════════════════════════════════════════════════════════════════

export function getDoseRespostaChallenges(): ChallengeSet {
  return { title: "Desafio: Curva Dose-Resposta", description: "Potência, eficácia, agonistas parciais e antagonismo.", challenges: [
    { type: "mcq", question: "O EC50 representa:", options: ["A dose que causa 50% de mortalidade", "A concentração que produz 50% do efeito máximo", "A dose mínima eficaz", "A concentração tóxica"], correctIndex: 1, explanation: "EC50 é a concentração efetiva que produz 50% do Emax. Menor EC50 = maior potência.", reference: "Rang & Dale, Cap. 2" },
    { type: "mcq", question: "Um agonista parcial é caracterizado por:", options: ["EC50 elevado", "Emax inferior ao agonista pleno", "Ausência de afinidade pelo receptor", "Ligação irreversível"], correctIndex: 1, explanation: "Agonistas parciais têm atividade intrínseca <1, produzindo Emax menor. Podem funcionar como antagonistas funcionais em presença de agonista pleno.", reference: "Katzung, Cap. 2" },
    { type: "mcq", question: "O antagonismo competitivo causa:", options: ["↓ Emax sem alterar EC50", "↑ EC50 sem alterar Emax", "↓ EC50 e ↓ Emax", "Nenhuma alteração"], correctIndex: 1, explanation: "O antagonista competitivo desloca a curva para a direita (↑EC50) mas o Emax pode ser restaurado aumentando [agonista].", reference: "Rang & Dale, Cap. 2" },
    { type: "mcq", question: "A naloxona reverte overdose de opioides porque é um:", options: ["Agonista parcial µ", "Antagonista competitivo µ", "Agonista inverso", "Inibidor enzimático"], correctIndex: 1, explanation: "Naloxona compete pelo receptor µ-opioide, deslocando morfina/fentanil. Meia-vida curta: doses repetidas podem ser necessárias.", reference: "Katzung, Cap. 31" },
    { type: "mcq", question: "No antagonismo não-competitivo irreversível:", options: ["Aumentar [agonista] restaura Emax", "O Emax é reduzido permanentemente", "O EC50 aumenta sem alterar Emax", "Não há efeito farmacológico"], correctIndex: 1, explanation: "Ligação covalente inativa receptores permanentemente. Recuperação depende de síntese de novos receptores (turnover).", reference: "Rang & Dale, Cap. 2" },
    { type: "mcq", question: "A potência relativa entre dois fármacos é determinada comparando:", options: ["Seus Emax", "Seus EC50", "Suas meias-vidas", "Seus volumes de distribuição"], correctIndex: 1, explanation: "Potência = posição da curva no eixo X (EC50). Eficácia = altura máxima (Emax). São conceitos independentes.", reference: "Goodman & Gilman, Cap. 3" },
    { type: "adjust", question: "Simule um agonista parcial: reduza o Emax para ~55% mantendo o EC50.", targetParams: { emax: { min: 45, max: 65, label: "Emax" } }, validator: (s) => { const e = s.emax ?? 100; return (e >= 45 && e <= 65) ? { correct: true, feedback: "Agonista parcial simulado!" } : { correct: false, feedback: `Emax: ${e}%. Ajuste para 45-65%.` }; }, explanation: "Agonistas parciais como buprenorfina têm atividade intrínseca ~0.5, produzindo cerca de 55% do efeito máximo.", reference: "Rang & Dale, Cap. 2" },
    { type: "mcq", question: "A teoria de receptores de reserva (spare receptors) explica:", options: ["Por que o Emax é sempre 100%", "Como o efeito máximo pode ser atingido sem ocupar todos os receptores", "A ligação irreversível dos antagonistas", "A dessensibilização homóloga"], correctIndex: 1, explanation: "Se há receptores de reserva, Emax é atingido com <100% de ocupação. O antagonismo irreversível reduz Emax apenas após consumir os receptores de reserva.", reference: "Katzung, Cap. 2" },
  ]};
}

export function getTransducaoSinalChallenges(): ChallengeSet {
  return { title: "Desafio: Transdução de Sinal", description: "Receptores, cascatas intracelulares e bloqueios farmacológicos.", challenges: [
    { type: "mcq", question: "O receptor β2-adrenérgico está acoplado a:", options: ["Gi → ↓AMPc", "Gs → ↑AMPc", "Gq → IP₃/DAG", "Canal iônico"], correctIndex: 1, explanation: "β2 → Gs → adenilato ciclase → ↑AMPc → PKA → relaxamento do músculo liso brônquico.", reference: "Rang & Dale, Cap. 3" },
    { type: "mcq", question: "A via IP₃/DAG é ativada por receptores acoplados a:", options: ["Gs", "Gi", "Gq", "Receptor nuclear"], correctIndex: 2, explanation: "Gq ativa PLC → PIP₂ → IP₃ (libera Ca²⁺ do RE) + DAG (ativa PKC).", reference: "Goodman & Gilman, Cap. 3" },
    { type: "mcq", question: "Os receptores nucleares (ex: glicocorticoides) têm latência de:", options: ["Milissegundos", "Segundos", "Minutos", "Horas a dias"], correctIndex: 3, explanation: "Receptores nucleares modulam transcrição gênica. O efeito requer síntese proteica → latência de horas a dias.", reference: "Rang & Dale, Cap. 3" },
    { type: "mcq", question: "A dessensibilização β-adrenérgica envolve:", options: ["Aumento de AMPc", "Fosforilação por GRK e recrutamento de β-arrestina", "Upregulation de receptores", "Bloqueio de Gs"], correctIndex: 1, explanation: "Uso crônico de β-agonistas: GRK fosforila receptor → β-arrestina → internalização → dessensibilização. Base da taquifilaxia.", reference: "Katzung, Cap. 2" },
    { type: "mcq", question: "A insulina ativa qual tipo de receptor?", options: ["GPCR Gs", "Canal iônico (nAChR)", "Receptor tirosina quinase", "Receptor nuclear"], correctIndex: 2, explanation: "Receptor de insulina: tirosina quinase → IRS → PI3K/Akt → translocação GLUT4 + via MAPK (crescimento celular).", reference: "Goodman & Gilman, Cap. 47" },
    { type: "mcq", question: "O omeprazol inibe irreversivelmente:", options: ["A adenilato ciclase", "A bomba H⁺/K⁺-ATPase", "O receptor H2", "A fosfolipase C"], correctIndex: 1, explanation: "Omeprazol é pró-fármaco ativado no canalículo ácido. Liga-se covalentemente à H⁺/K⁺-ATPase (inibição irreversível).", reference: "Katzung, Cap. 62" },
    { type: "mcq", question: "A via JAK-STAT é associada a receptores de:", options: ["Insulina", "Citocinas (IL, IFN, EPO)", "Acetilcolina", "Noradrenalina"], correctIndex: 1, explanation: "Receptores de citocinas não têm atividade quinase intrínseca. Recrutam JAK → fosforila STAT → dimeriza → núcleo → transcrição.", reference: "Rang & Dale, Cap. 3" },
    { type: "mcq", question: "A toxina pertussis bloqueia:", options: ["Gs (ativa adenilato ciclase)", "Gi (impede inibição de adenilato ciclase)", "Gq (bloqueia PLC)", "Canais de Na⁺"], correctIndex: 1, explanation: "Toxina pertussis ADP-ribosila Gi, impedindo sua ativação. Resultado: ↑AMPc constitutivo → efeitos da coqueluche.", reference: "Goodman & Gilman, Cap. 3" },
  ]};
}

export function getJanelaTerapeuticaFarmaChallenges(): ChallengeSet {
  return { title: "Desafio: Janela Terapêutica", description: "Índice terapêutico, fármacos de janela estreita e TDM.", challenges: [
    { type: "mcq", question: "O índice terapêutico é calculado como:", options: ["DE50/DL50", "DL50/DE50", "Emax/EC50", "Cmax/Cmin"], correctIndex: 1, explanation: "IT = DL50/DE50. Quanto maior, mais seguro. IT<3 indica janela estreita (TDM necessário).", reference: "Katzung, Cap. 4" },
    { type: "mcq", question: "Qual destes tem janela terapêutica ESTREITA?", options: ["Amoxicilina", "Ibuprofeno", "Lítio", "Paracetamol"], correctIndex: 2, explanation: "Lítio: faixa 0.6-1.2 mEq/L. Acima de 1.5 → toxicidade. IT ≈ 2-3. Requer litemia regular.", reference: "Stahl's Essential Psychopharmacology" },
    { type: "mcq", question: "O monitoramento terapêutico de fármacos (TDM) é obrigatório para:", options: ["Antibióticos de amplo espectro", "Fármacos com IT amplo", "Fármacos com IT estreito e alta variabilidade PK", "Todos os fármacos orais"], correctIndex: 2, explanation: "TDM é essencial para: vancomicina, aminoglicosídeos, digoxina, lítio, antiepilépticos, imunossupressores.", reference: "Burton ME. Applied Pharmacokinetics" },
    { type: "mcq", question: "A margem de segurança é definida como:", options: ["DL1/DE99", "DL50/DE50", "Cmax/MIC", "AUC/MIC"], correctIndex: 0, explanation: "Margem de segurança (DL1/DE99) é mais conservadora que o IT. Considera doses que afetam 1% da população (toxicidade) vs 99% (eficácia).", reference: "Goodman & Gilman, Cap. 4" },
    { type: "adjust", question: "Configure uma janela estreita: faça DE50 e DL50 ficarem próximos (IT < 2.5).", targetParams: { de50: { min: 30, max: 50, label: "DE50" }, dl50: { min: 50, max: 80, label: "DL50" } }, validator: (s) => { const it = (s.dl50 ?? 65) / (s.de50 ?? 30); return it < 2.5 ? { correct: true, feedback: `IT = ${it.toFixed(1)} — janela estreita!` } : { correct: false, feedback: `IT = ${it.toFixed(1)}. Aproxime DE50 e DL50.` }; }, explanation: "Fármacos com IT < 2.5 requerem TDM rigoroso e individualização de dose.", reference: "Katzung, Cap. 4" },
    { type: "mcq", question: "A hipocalemia potencializa a toxicidade de qual fármaco?", options: ["Lítio", "Vancomicina", "Digoxina", "Fenitoína"], correctIndex: 2, explanation: "Digoxina compete com K⁺ pela Na⁺/K⁺-ATPase. Hipocalemia → mais ligação da digoxina → toxicidade mesmo em níveis séricos normais.", reference: "Harrison's, Cap. 236" },
    { type: "mcq", question: "O conceito de 'dose de carga' é importante para fármacos com:", options: ["Meia-vida curta", "IT amplo", "Meia-vida longa (demora para atingir Css)", "Baixa biodisponibilidade"], correctIndex: 2, explanation: "Fármacos com t½ longa (ex: digoxina t½=36h) demoram 5 meias-vidas (~7 dias) para atingir Css. Dose de carga antecipa esse equilíbrio.", reference: "Rowland & Tozer, Cap. 11" },
  ]};
}

export function getViasAdministracaoChallenges(): ChallengeSet {
  return { title: "Desafio: Vias de Administração", description: "Farmacocinética comparada entre vias.", challenges: [
    { type: "mcq", question: "A biodisponibilidade de um fármaco IV é:", options: ["50%", "75%", "90%", "100%"], correctIndex: 3, explanation: "Via IV: sem absorção, sem efeito de primeira passagem. F = 100% por definição.", reference: "Goodman & Gilman, Cap. 2" },
    { type: "mcq", question: "O efeito de primeira passagem afeta principalmente a via:", options: ["Intravenosa", "Intramuscular", "Oral", "Sublingual"], correctIndex: 2, explanation: "Via oral → veia porta → fígado (metabolismo de 1ª passagem) → circulação sistêmica. Pode reduzir F drasticamente (nitroglicerina oral F~1%).", reference: "Katzung, Cap. 3" },
    { type: "mcq", question: "A via sublingual evita o efeito de primeira passagem porque:", options: ["Absorve pelo estômago", "Drena diretamente para a veia cava (não passa pelo fígado)", "É mais lenta que a oral", "Requer formulação especial"], correctIndex: 1, explanation: "Mucosa sublingual → veias linguais → veia jugular interna → veia cava superior → coração, bypassing o fígado.", reference: "Rang & Dale, Cap. 8" },
    { type: "mcq", question: "Na anafilaxia, a via preferida para adrenalina é:", options: ["IV", "Oral", "IM (face anterolateral da coxa)", "Subcutânea"], correctIndex: 2, explanation: "IM na coxa: absorção rápida e previsível. IV tem risco de arritmia. SC é errática por vasoconstrição local.", reference: "WAO Anaphylaxis Guidelines 2020" },
    { type: "mcq", question: "A AUC (Área Sob a Curva) é proporcional a:", options: ["Cmax apenas", "Tmax apenas", "Exposição total ao fármaco", "Velocidade de absorção"], correctIndex: 2, explanation: "AUC reflete a exposição total (quantidade absorvida/F × dose / clearance). Bioequivalência: AUC teste / AUC referência = 80-125%.", reference: "Rowland & Tozer, Cap. 7" },
    { type: "mcq", question: "Via transdérmica é ideal para fármacos com:", options: ["Peso molecular >500 Da", "Alta hidrofilia", "Alta lipofilia e baixa dose diária", "Meia-vida ultracurta"], correctIndex: 2, explanation: "Pele é barreira lipofílica. Fármacos ideais: lipossolúveis, PM<500, dose baixa (ex: fentanil patch 25-100 µg/h).", reference: "Katzung, Cap. 3" },
    { type: "mcq", question: "O Tmax é mais curto para qual via?", options: ["Oral", "Subcutânea", "IV bolus", "Retal"], correctIndex: 2, explanation: "IV bolus: Tmax = 0 (concentração máxima instantânea). Seguido por sublingual (~5 min) > IM (~30 min) > oral (~60-90 min).", reference: "Goodman & Gilman, Cap. 2" },
  ]};
}

export function getBloqueioNeuromuscularChallenges(): ChallengeSet {
  return { title: "Desafio: Bloqueio Neuromuscular", description: "Despolarizantes, não-despolarizantes e reversão.", challenges: [
    { type: "mcq", question: "A succinilcolina causa fasciculações porque:", options: ["Bloqueia a AChE", "Despolariza a placa motora antes de bloquear", "Ativa receptores muscarínicos", "Inibe a recaptação de ACh"], correctIndex: 1, explanation: "Succinilcolina é agonista nicotínico: despolarização inicial → fasciculações → bloqueio sustentado (fase I) por dessensibilização.", reference: "Stoelting's, Cap. 12" },
    { type: "mcq", question: "O sugammadex reverte o bloqueio do rocurônio por:", options: ["Inibição da AChE", "Encapsulamento direto da molécula de rocurônio", "Ativação de receptores nicotínicos", "Bloqueio de canais de Ca²⁺"], correctIndex: 1, explanation: "Sugammadex é uma γ-ciclodextrina que forma complexo 1:1 com rocurônio/vecurônio, removendo-os do receptor. Reversão em <3 min.", reference: "Naguib M. Anesthesiology 2007" },
    { type: "mcq", question: "TOF ratio ≥ 0.9 indica:", options: ["Bloqueio profundo", "Bloqueio moderado", "Recuperação adequada para extubação", "Necessidade de mais relaxante"], correctIndex: 2, explanation: "TOF (Train-of-Four) ratio ≥0.9 é critério de segurança para extubação. <0.9 = curarização residual com risco de aspiração.", reference: "Murphy GS. Anesth Analg 2010" },
    { type: "mcq", question: "A neostigmina reverte bloqueio não-despolarizante porque:", options: ["Bloqueia receptores nicotínicos", "Inibe AChE → ↑ACh na fenda → compete com relaxante", "Encapsula o relaxante", "Ativa Gs"], correctIndex: 1, explanation: "Neostigmina é anticolinesterásico: ↑ACh na junção NM → desloca o antagonista competitivo. Dar com atropina para bloquear efeitos muscarínicos.", reference: "Stoelting's, Cap. 12" },
    { type: "mcq", question: "Qual é contraindicação absoluta da succinilcolina?", options: ["Alergia a látex", "Hipercalemia conhecida", "Hipertensão arterial", "Idade > 65 anos"], correctIndex: 1, explanation: "Succinilcolina causa efluxo de K⁺ das células musculares. Em hipercalemia, queimaduras, desnervação → risco de PCR por hipercalemia fatal.", reference: "Miller's Anesthesia, Cap. 34" },
    { type: "mcq", question: "O bloqueio fase II (dual block) da succinilcolina:", options: ["Ocorre após dose única", "Ocorre com doses repetidas/infusão prolongada", "É revertido com mais succinilcolina", "Nunca ocorre na prática"], correctIndex: 1, explanation: "Fase II: após infusão prolongada ou doses repetidas, o bloqueio muda de despolarizante para não-despolarizante (fade no TOF). Pode ser parcialmente revertido com neostigmina.", reference: "Stoelting's, Cap. 12" },
    { type: "mcq", question: "Em paciente com miastenia gravis, a dose de rocurônio deve ser:", options: ["Aumentada 2×", "Dose normal", "Reduzida significativamente (1/5 a 1/10)", "Evitada completamente"], correctIndex: 2, explanation: "MG: menos receptores nicotínicos funcionais → sensibilidade aumentada a não-despolarizantes. Usar 10-20% da dose habitual com monitorização TOF.", reference: "Barash Clinical Anesthesia, Cap. 38" },
  ]};
}

export function getFarmacoAutonomicaChallenges(): ChallengeSet {
  return { title: "Desafio: Farmacologia Autonômica", description: "Agonistas e antagonistas adrenérgicos e colinérgicos aplicados.", challenges: [
    { type: "mcq", question: "A atropina causa taquicardia porque:", options: ["Ativa β1", "Bloqueia M2 no nó SA → remove tônus vagal", "Ativa α1 nos vasos", "Inibe a MAO"], correctIndex: 1, explanation: "Atropina antagoniza M2 cardíaco: remove o freio vagal → desinibição do nó SA → taquicardia.", reference: "Rang & Dale, Cap. 13" },
    { type: "mcq", question: "A fenilefrina é usada em hipotensão porque:", options: ["Ativa β2 → vasodilatação", "Ativa α1 → vasoconstrição → ↑PA", "Bloqueia M3 → ↑FC", "Ativa β1 → ↑DC"], correctIndex: 1, explanation: "Fenilefrina: agonista α1 seletivo → vasoconstrição arterial → ↑RVP → ↑PA. Reflexamente pode causar bradicardia.", reference: "Katzung, Cap. 9" },
    { type: "mcq", question: "No feocromocitoma, por que β-bloqueio ANTES de α-bloqueio é perigoso?", options: ["Causa bradicardia letal", "Remove vasodilatação β2, deixando α1 sem oposição → crise hipertensiva", "Bloqueia secreção de catecolaminas", "Causa hipoglicemia"], correctIndex: 1, explanation: "β2 nos vasos causa vasodilatação. Se bloqueado sem α-bloqueio prévio, a vasoconstrição α1 fica sem oposição → crise hipertensiva paradoxal.", reference: "Harrison's, Cap. 381" },
    { type: "mcq", question: "A pilocarpina causa miose porque:", options: ["Ativa α1 no músculo radial", "Ativa M3 no músculo esfíncter da pupila", "Bloqueia β2 na íris", "Inibe a ACh"], correctIndex: 1, explanation: "M3 no músculo esfíncter (circular) da íris → contração → miose. Também contrai músculo ciliar → acomodação (visão para perto).", reference: "Rang & Dale, Cap. 13" },
    { type: "mcq", question: "O propranolol é contraindicado na asma porque:", options: ["Ativa M3 nos brônquios", "Bloqueia β2 → broncoconstrição", "Causa alergia cruzada", "Aumenta secreção de histamina"], correctIndex: 1, explanation: "β2 no músculo liso brônquico causa broncodilatação. Propranolol (não-seletivo) bloqueia β2 → broncoconstrição. Usar β1-seletivos (metoprolol) com cautela.", reference: "Katzung, Cap. 10" },
    { type: "mcq", question: "A noradrenalina endógena atua preferencialmente em:", options: ["β2 > β1 > α1", "α1 ≈ β1 >> β2", "M2 > M3", "α2 apenas"], correctIndex: 1, explanation: "Noradrenalina: potente agonista α1 e β1, fraco em β2. Clinicamente: vasoconstrição (α1) + ↑FC e contratilidade (β1).", reference: "Goodman & Gilman, Cap. 12" },
    { type: "mcq", question: "O isoproterenol é um agonista puro de:", options: ["α1 e α2", "β1 e β2 (sem efeito α)", "Muscarínicos", "Dopaminérgicos"], correctIndex: 1, explanation: "Isoproterenol: β1 (↑FC, ↑contratilidade) + β2 (vasodilatação, broncodilatação). Sem efeito α. Uso clínico limitado (risco arrítmico).", reference: "Katzung, Cap. 9" },
  ]};
}

export function getToleranciaDependenciaChallenges(): ChallengeSet {
  return { title: "Desafio: Tolerância e Dependência", description: "Mecanismos de tolerância, dependência física e síndrome de abstinência.", challenges: [
    { type: "mcq", question: "A tolerância farmacodinâmica a opioides envolve:", options: ["Aumento da absorção", "Downregulation e dessensibilização de receptores µ", "Indução enzimática CYP3A4", "Aumento da excreção renal"], correctIndex: 1, explanation: "Uso crônico: fosforilação do receptor µ (GRK) → β-arrestina → internalização → dessensibilização. Menos receptores funcionais na superfície.", reference: "Rang & Dale, Cap. 42" },
    { type: "mcq", question: "A síndrome de abstinência de benzodiazepínicos pode incluir:", options: ["Sonolência extrema", "Convulsões", "Bradicardia", "Hipotensão severa"], correctIndex: 1, explanation: "BZD crônico → upregulation glutamatérgica compensatória. Retirada → hiperexcitabilidade → ansiedade, insônia, tremor, convulsões.", reference: "Ashton Manual" },
    { type: "mcq", question: "O delirium tremens na abstinência alcoólica tipicamente ocorre:", options: ["Nas primeiras 6 horas", "Em 24-48 horas", "Em 48-96 horas", "Após 2 semanas"], correctIndex: 2, explanation: "Timeline: tremores (6-24h) → convulsões (24-48h) → alucinações (24-72h) → delirium tremens (48-96h). DT tem mortalidade de 5-15% sem tratamento.", reference: "Harrison's, Cap. 448" },
    { type: "mcq", question: "A tolerância cruzada entre BZD e álcool ocorre porque:", options: ["Ambos são metabolizados pelo CYP2D6", "Ambos potenciam GABA-A", "Ambos bloqueiam NMDA", "Ambos ativam receptores µ"], correctIndex: 1, explanation: "BZD e álcool atuam no receptor GABA-A (sítios diferentes). A adaptação do receptor a um confere tolerância parcial ao outro.", reference: "Stahl's Essential Psychopharmacology" },
    { type: "mcq", question: "O protocolo de Ashton para desmame de BZD recomenda:", options: ["Suspensão abrupta", "Troca para BZD de meia-vida longa + redução gradual", "Aumento da dose antes de suspender", "Substituição por opioides"], correctIndex: 1, explanation: "Ashton: converter para diazepam (t½ longa, menos flutuação) → reduzir 10-25% a cada 2-4 semanas → monitorar sintomas.", reference: "Ashton CH. Benzodiazepines: How They Work and How to Withdraw" },
    { type: "mcq", question: "A tolerância à depressão respiratória por opioides:", options: ["Nunca se desenvolve", "Desenvolve-se mais lentamente que a tolerância analgésica", "Desenvolve-se mais rapidamente", "É idêntica à tolerância analgésica"], correctIndex: 1, explanation: "Tolerância diferencial: analgesia (rápida) > euforia > sedação > depressão respiratória (lenta) > miose e constipação (mínima).", reference: "Katzung, Cap. 31" },
    { type: "mcq", question: "Tiamina IV deve ser administrada ANTES de glicose no etilismo porque:", options: ["Previne hipoglicemia", "Glicose sem tiamina pode precipitar encefalopatia de Wernicke", "Tiamina aumenta absorção de glicose", "Previne convulsões"], correctIndex: 1, explanation: "A glicose consome tiamina residual no metabolismo. Em etilistas com reservas depletadas, isso precipita Wernicke (oftalmoplegia, ataxia, confusão).", reference: "Harrison's, Cap. 448" },
  ]};
}

export function getFarmacogenomicaChallenges(): ChallengeSet {
  return { title: "Desafio: Farmacogenômica", description: "Polimorfismos CYP e medicina personalizada.", challenges: [
    { type: "mcq", question: "Um metabolizador lento (PM) de CYP2D6 usando codeína terá:", options: ["Excesso de morfina → toxicidade", "Pouca conversão em morfina → analgesia insuficiente", "Efeito normal", "Reação alérgica"], correctIndex: 1, explanation: "Codeína é pró-fármaco → morfina via CYP2D6. PM: pouca ativação → analgesia insuficiente. UM: excesso de morfina → depressão respiratória.", reference: "CPIC Guideline for CYP2D6 and Codeine" },
    { type: "mcq", question: "O CPIC (Clinical Pharmacogenetics Implementation Consortium) recomenda para CYP2C19 PM usando clopidogrel:", options: ["Dobrar a dose", "Trocar para prasugrel ou ticagrelor", "Manter dose padrão", "Adicionar aspirina em dose alta"], correctIndex: 1, explanation: "Clopidogrel (pró-fármaco) depende de CYP2C19. PM: menor ativação → maior risco de trombose de stent. Prasugrel/ticagrelor não dependem.", reference: "CPIC Guideline for CYP2C19 and Clopidogrel" },
    { type: "mcq", question: "Metabolizadores ultrarrápidos (UM) de CYP2D6 usando um fármaco ATIVO terão:", options: ["Acúmulo e toxicidade", "Metabolização excessiva → falha terapêutica", "Efeito normal", "Nenhum efeito do genótipo"], correctIndex: 1, explanation: "UM + fármaco ativo = inativação acelerada → níveis subterapêuticos. Necessário aumento de dose ou troca por fármaco não-CYP2D6.", reference: "Crews KR et al. Clin Pharmacol Ther 2014" },
    { type: "mcq", question: "A farmacogenômica da varfarina envolve quais genes principais?", options: ["CYP3A4 e MDR1", "CYP2C9 e VKORC1", "CYP2D6 e CYP1A2", "NAT2 e TPMT"], correctIndex: 1, explanation: "CYP2C9 (metabolismo) + VKORC1 (alvo farmacológico) explicam ~40% da variabilidade de dose. Alelos *2/*3 e -1639G>A.", reference: "Johnson JA et al. Clin Pharmacol Ther 2017" },
    { type: "mcq", question: "O teste de HLA-B*57:01 é obrigatório antes de usar:", options: ["Clopidogrel", "Abacavir", "Varfarina", "Metformina"], correctIndex: 1, explanation: "HLA-B*5701 positivo: risco de hipersensibilidade grave ao abacavir (síndrome de Stevens-Johnson). Teste obrigatório pelo FDA.", reference: "Mallal S et al. N Engl J Med 2008" },
    { type: "mcq", question: "A deficiência de G6PD é relevante na farmacogenômica porque:", options: ["Afeta metabolismo CYP", "Pacientes hemolisam com fármacos oxidantes (primaquina, dapsona, sulfonamidas)", "Causa resistência a antibióticos", "Altera absorção oral"], correctIndex: 1, explanation: "G6PD gera NADPH para manter glutationa reduzida. Deficientes expostos a oxidantes → hemólise. ~400 milhões de pessoas afetadas globalmente.", reference: "Cappellini MD et al. Lancet 2008" },
    { type: "mcq", question: "A tiopurina metiltransferase (TPMT) é testada antes do uso de:", options: ["Metotrexato", "Azatioprina/6-mercaptopurina", "Ciclosporina", "Tacrolimus"], correctIndex: 1, explanation: "TPMT inativa tiopurinas. Deficientes (0.3%): acúmulo de metabólitos ativos → mielossupressão grave/fatal. Genotipar antes de prescrever.", reference: "Relling MV et al. Clin Pharmacol Ther 2011" },
  ]};
}

