    "cinetica-avancada": getCineticaAvancadaChallenges,
    "ciclo-ureia": getCicloUreiaChallenges,
    "acido-araquidonico": getCascataAcidoAraquidonicoChallenges,
    "lipoproteinas": getLipoproteinasChallenges,
    "pentoses-fosfato": getPentosesFosfatoChallenges,
    "titulacao-aminoacidos": getTitulacaoAminoacidosChallenges,
    "operon-lac": getOperonLacChallenges,
    "dose-resposta": getDoseRespostaChallenges,
    "transducao-sinal": getTransducaoSinalChallenges,
    "janela-terapeutica-farma": getJanelaTerapeuticaFarmaChallenges,
    "vias-administracao": getViasAdministracaoChallenges,
    "bloqueio-neuromuscular": getBloqueioNeuromuscularChallenges,
    "farmaco-autonomica": getFarmacoAutonomicaChallenges,
    "tolerancia-dependencia": getToleranciaDependenciaChallenges,
